-----------------------------------
-- Pure helpers (no game API)
-----------------------------------
function M.adler32(s)
    local a, b = 1, 0
    for i = 1, #s do
        a = (a + s:byte(i)) % 65521
        b = (b + a) % 65521
    end

    return b * 65536 + a
end

function M.hex8(n)
    local hi = math.floor(n / 65536)
    local lo = n % 65536
    return string.format('%04x%04x', hi, lo)
end

-- bits: table id -> true ; count: number of ids (0..count-1)
function M.encodeBitmap(bits, count)
    local digits = {}
    local nd     = math.ceil(count / 4)
    for j = 0, nd - 1 do
        local v = 0
        for k = 0, 3 do
            if bits[4 * j + k] then
                v = v + 2 ^ k
            end
        end

        digits[#digits + 1] = string.format('%x', v)
    end

    return string.format('%d:%s', count, table.concat(digits))
end

-- offers: list of { cur = 'g'|'c'|'i'|'f'|'n', amount = n } -> "g500+c50"
function M.encodeOffers(offers)
    local parts = {}
    for _, o in ipairs(offers) do
        parts[#parts + 1] = o.cur .. tostring(o.amount)
    end

    return table.concat(parts, '+')
end

-- Build a body string from an ordered list of { key, value }.
function M.encodeBody(pairsList)
    local parts = {}
    for _, kv in ipairs(pairsList) do
        parts[#parts + 1] = kv[1] .. '=' .. kv[2]
    end

    return table.concat(parts, ';')
end

-- Split a body into frames. Returns list of frame strings or nil, err.
function M.frame(rid, kind, body)
    if #body < 1 or #body > M.config.maxBody then
        return nil, 'body length'
    end

    local chunks = {}
    local size   = M.config.chunkSize
    for i = 1, #body, size do
        chunks[#chunks + 1] = body:sub(i, i + size - 1)
    end

    local total  = #chunks
    local prefix = string.format('#fpx%d %s ', M.VERSION, rid)
    local frames = {}
    frames[1] = string.format('%s0/%d %s,%d,%s', prefix, total, kind, #body, M.hex8(M.adler32(body)))
    for i, c in ipairs(chunks) do
        frames[#frames + 1] = string.format('%s%d/%d %s', prefix, i, total, c)
    end

    return frames
end

local HEX4  = '^[0-9a-f][0-9a-f][0-9a-f][0-9a-f]$'
local HEX12 = '^' .. string.rep('[0-9a-f]', 12) .. '$'

-- Parse a request line (the text after "!fpx "):
--   <ver> <sid> <rid> SYNC
--   <ver> <sid> <rid> GO <cat> <dest> <cur> <amount>
-- <sid> is the client session id (12 lowercase hex, new on every addon load,
-- PROTOCOL-FPX1.md §3); the replay cache is keyed by sid and rid together.
-- Returns table or nil, code, rid.
function M.parseRequest(line)
    if type(line) ~= 'string' then
        return nil, 'BADREQ', '0000'
    end

    if #line > M.config.maxLine then
        return nil, 'BADREQ', '0000'
    end

    if line:find('[^\32-\126]') then
        return nil, 'BADREQ', '0000'
    end

    local tokens = {}
    for tok in line:gmatch('%S+') do
        tokens[#tokens + 1] = tok
        if #tokens > M.config.maxTokens then
            return nil, 'BADREQ', '0000'
        end
    end

    local ver, sid, rid, op = tokens[1], tokens[2], tokens[3], tokens[4]

    -- The id to answer with: the RID token if it is one.
    local answerRid = '0000'
    if rid ~= nil and rid:match(HEX4) and rid ~= '0000' then
        answerRid = rid
    end

    if ver == nil or not ver:match('^%d%d?$') then
        return nil, 'BADREQ', answerRid
    end

    if tonumber(ver) ~= M.VERSION then
        return nil, 'VERSION', answerRid
    end

    if answerRid == '0000' then
        return nil, 'BADREQ', '0000'
    end

    if sid == nil or not sid:match(HEX12) then
        return nil, 'BADREQ', rid
    end

    if op == 'SYNC' then
        if #tokens ~= 4 then
            return nil, 'BADREQ', rid
        end

        return { sid = sid, rid = rid, op = 'SYNC' }
    elseif op == 'GO' then
        if #tokens ~= 8 then
            return nil, 'BADREQ', rid
        end

        local cat, dest, cur, amount = tokens[5], tokens[6], tokens[7], tokens[8]
        if not cat:match('^[HSGR]$') then
            return nil, 'BADREQ', rid
        end

        if not dest:match('^%d%d?%d?$') or not cur:match('^[gcif]$') or not amount:match('^%d%d?%d?%d?%d?%d?%d?%d?%d?$') then
            return nil, 'BADREQ', rid
        end

        amount = tonumber(amount)
        if cur == 'f' and amount ~= 0 then
            return nil, 'BADREQ', rid
        end

        return { sid = sid, rid = rid, op = 'GO', cat = cat, dest = tonumber(dest), cur = cur, amount = amount }
    end

    return nil, 'BADREQ', rid
end

