-- Survival guide table (LSB survival_guide_map.lua), loaded lazily.
function M.survivalGuides()
    if M._sg == nil then
        local ok, mod = pcall(require, 'scripts/globals/teleports/survival_guide_map')
        if ok and type(mod) == 'table' and type(mod.survivalGuides) == 'table' then
            M._sg = mod.survivalGuides
        else
            M._sg = {}
        end
    end

    return M._sg
end

local function teleportType(name, fallback)
    local t = xi and xi.teleport and xi.teleport.type
    return (t and t[name]) or fallback
end

local function keyItem(name)
    return xi and xi.keyItem and xi.keyItem[name]
end

local function teleDest(name)
    local ids  = xi and xi.teleport and xi.teleport.id
    local dest = xi and xi.teleport and xi.teleport.destination
    if ids == nil or dest == nil or ids[name] == nil then
        return nil
    end

    return dest[ids[name]]
end

-- Returns { x, y, z, rot, zone } or nil.
function M.destination(cat, id)
    if cat == 'H' then
        local h = HP[id]
        if h then
            return { h[3], h[4], h[5], h[6], h[7] }
        end
    elseif cat == 'S' then
        local g = M.survivalGuides()[id]
        if g and id < M.SG_COUNT then
            return { g.posX, g.posY, g.posZ, g.posRot, g.zoneId }
        end
    elseif cat == 'G' then
        local g = M.gateCrystals[id]
        if g then
            return teleDest(g.tele)
        end
    elseif cat == 'R' then
        local r = M.runicPortals[id]
        if r then
            return teleDest(r.tele)
        end
    end

    return nil
end

local function validDest(d)
    if type(d) ~= 'table' then
        return false
    end

    for i = 1, 5 do
        if type(d[i]) ~= 'number' then
            return false
        end
    end

    return true
end

function M.isUnlocked(player, cat, id)
    if cat == 'H' then
        return HP[id] ~= nil and player:hasTeleport(teleportType('HOMEPOINT', 9), id % 32, math.floor(id / 32)) == true
    elseif cat == 'S' then
        local g = M.survivalGuides()[id]
        return g ~= nil and player:hasTeleport(teleportType('SURVIVAL', 10), g.groupIndex - 1, g.group - 1) == true
    elseif cat == 'G' then
        local g = M.gateCrystals[id]
        local ki = g and keyItem(g.ki)
        return ki ~= nil and player:hasKeyItem(ki) == true
    elseif cat == 'R' then
        if M.runicPortals[id] == nil then
            return false
        end

        local mask = player:getTeleport(teleportType('RUNIC_PORTAL', 3)) or 0
        return math.floor(mask / 2 ^ id) % 2 == 1
    end

    return false
end

