    [239] = 3, -- windurst_walls (Windurst)
    [240] = 3, -- port_windurst (Windurst)
    [241] = 3, -- windurst_woods (Windurst)
    [242] = 3, -- heavens_tower (Windurst; no Home Point, type city)
    [243] = 4, -- rulude_gardens (Jeuno)
    [244] = 4, -- upper_jeuno (Jeuno)
    [245] = 4, -- lower_jeuno (Jeuno)
    [246] = 4, -- port_jeuno (Jeuno)
    [247] = 9, -- rabao (Kuzotz)
    [252] = 8, -- norg (ElshimoLowlands)
    [256] = 5, -- western_adoulin (AdoulinIslands)
    [257] = 5, -- eastern_adoulin (AdoulinIslands)
}

function M.cityOf(zoneId)
    return M.cityGroupOfZone[zoneId]
end

-- True when origin and destination zones are in the same city.
function M.sameCity(originZone, destZone)
    local a = M.cityOf(originZone)
    return a ~= nil and a == M.cityOf(destZone)
end

local function copyOffers(list)
    local out = {}
    for i, o in ipairs(list) do
        out[i] = { cur = o.cur, amount = o.amount }
    end

    return out
end

-----------------------------------
-- Price configuration (1.2.0): validated once when the module loads
-----------------------------------
M.DEFAULT_PRICES =
{
    H = { { cur = 'g', amount = 1000 }, { cur = 'c', amount = 100 } },
    S = { { cur = 'g', amount = 1000 }, { cur = 'c', amount = 100 } },
    G = { { cur = 'g', amount = 1000 }, { cur = 'c', amount = 100 } },
    R = { { cur = 'g', amount = 1000 }, { cur = 'i', amount = 100 } },
}

-- Currencies a category may accept (they match the client's payment choices).
M.ALLOWED_CURRENCIES =
{
    H = { g = true, c = true },
    S = { g = true, c = true },
    G = { g = true, c = true },
    R = { g = true, i = true },
}

M.MAX_PRICE = 999999999 -- FPX/1 amounts have at most 9 digits

-- Validates one category's configured list. Returns offers or nil, why.
function M.validateCategory(cat, list)
    if type(list) ~= 'table' then
        return nil, 'must be a list of { cur = ..., amount = ... } entries'
    end

    local out, seen, zeros = {}, {}, 0

    for i, o in ipairs(list) do
        if type(o) ~= 'table' then
            return nil, 'entry ' .. i .. ' is not a table'
        end

        local cur, amount = o.cur, o.amount

        if not M.ALLOWED_CURRENCIES[cat][cur] then
            return nil, 'entry ' .. i .. ': currency ' .. tostring(cur) .. ' is not allowed for this category'
        end

        if seen[cur] then
            return nil, 'currency ' .. cur .. ' listed twice'
        end

        if type(amount) ~= 'number' or amount ~= amount or amount ~= math.floor(amount)
            or amount < 0 or amount > M.MAX_PRICE then
            return nil, 'entry ' .. i .. ': amount must be a whole number from 0 to ' .. M.MAX_PRICE
        end

        seen[cur] = true
        zeros = zeros + ((amount == 0) and 1 or 0)
        out[#out + 1] = { cur = cur, amount = amount }
    end

    if #out == 0 then
        return nil, 'at least one currency is required'
    end

    if zeros > 0 and zeros < #out then
        return nil, 'mixes free (0) and paid amounts; set every amount to 0 to make the category free'
    end

    if zeros == #out then
        return { { cur = 'f', amount = 0 } } -- free category
    end

    return out
end

-- Builds M.active from M.config. Invalid parts keep the defaults and are
-- logged. Returns the number of errors. Called at load; call again after
-- changing M.config at runtime (e.g. from a module reload or a test).
function M.applyConfig()
    local errors = 0
    local cfg = M.config
    local active = { prices = {}, sameCityFree = true }

    for _, cat in ipairs({ 'H', 'S', 'G', 'R' }) do
        local list, why = M.validateCategory(cat, cfg.prices and cfg.prices[cat])

        if list == nil then
            errors = errors + 1
            list = M.validateCategory(cat, M.DEFAULT_PRICES[cat])
            pcall(M.log, string.format('[fpxport] CONFIG ERROR prices.%s: %s. Using the default price for this category.', cat, why))
        end

        active.prices[cat] = list
    end

    if cfg.sameCityFree == nil or type(cfg.sameCityFree) == 'boolean' then
        active.sameCityFree = cfg.sameCityFree ~= false
    else
        errors = errors + 1
        pcall(M.log, '[fpxport] CONFIG ERROR sameCityFree must be true or false. Using true.')
    end

    M.active = active
    return errors
end

-- ctx caches per-request lookups. Returns the destination's offer list.
function M.offers(player, cat, id, ctx)
    ctx = ctx or {}

    if M.active == nil then
        M.applyConfig()
    end

    local fixed = M.active.prices[cat]
    local dest  = M.destination(cat, id)
    if fixed == nil or not validDest(dest) then
        return { { cur = 'n', amount = 0 } }
    end

    if fixed[1].cur == 'f' then
        return { { cur = 'f', amount = 0 } }
    end

    if ctx.origin == nil then
        ctx.origin = player:getZoneID()
    end

    if M.active.sameCityFree and M.sameCity(ctx.origin, dest[5]) then
        return { { cur = 'f', amount = 0 } }
    end

    return copyOffers(fixed)
end

-----------------------------------
-- Balances
-----------------------------------
function M.balances(player)
    return
    {
        g  = player:getGil() or 0,
        c  = player:getCP() or 0,
        i  = player:getCurrency('imperial_standing') or 0,
    }
end

local function balancePairs(list, b)
    list[#list + 1] = { 'g', tostring(b.g) }
    list[#list + 1] = { 'cp', tostring(b.c) }
    list[#list + 1] = { 'is', tostring(b.i) }
end

local function charge(player, cur, amount)
    if amount <= 0 or cur == 'f' then
        return
    end

    if cur == 'g' then
        player:delGil(amount)
    elseif cur == 'c' then
        player:delCP(amount)
    elseif cur == 'i' then
        player:delCurrency('imperial_standing', amount)
    end
end

local function refund(player, cur, amount)
    if amount <= 0 or cur == 'f' then
        return
    end

    if cur == 'g' then
        player:addGil(amount)
    elseif cur == 'c' then
        player:addCP(amount)
    elseif cur == 'i' then
        player:addCurrency('imperial_standing', amount)
    end
end

-----------------------------------
-- Character state / zone restrictions
-----------------------------------
local function enumValue(tbl, name)
    local t = xi and xi[tbl]
    return t and t[name]
end

-- Returns nil if travel is allowed, else an error code ('STATE' / 'ZONE').
function M.travelBlock(player)
    if player:getInstance() ~= nil then
        return 'ZONE'
    end

    local battlefield = enumValue('effect', 'BATTLEFIELD')
    if battlefield and player:hasStatusEffect(battlefield) then
        return 'ZONE'
    end

    local zone = player:getZoneID()
    local gaol = enumValue('zone', 'MORDION_GAOL') or 131
    if zone == gaol then
        return 'ZONE'
    end

    if player:isDead() then
        return 'STATE'
    end

    if player:isInEvent() then
        return 'STATE'
    end

    if player:isEngaged() or player:hasEnmity() then
        return 'STATE'
    end

    local anim = player:getAnimation()
    local choc = enumValue('animation', 'CHOCOBO') or 5
    local mount = enumValue('animation', 'MOUNT') or 85
    if anim == choc or anim == mount then
        return 'STATE'
    end

    if player:getLocalVar('ZoningIn') == 1 then
        return 'STATE'
    end

    return nil
end

-----------------------------------
-- Per-character session state (replay cache, rate limits)
-----------------------------------
M.sessions = {}

function M.now()
    return os.time()
end

local function session(charId)
    local s = M.sessions[charId]
    if s == nil then
        s = { replay = {}, order = {}, syncTimes = {}, goUntil = 0 }
        M.sessions[charId] = s
    end

    return s
end

function M.resetSession(charId)
    M.sessions[charId] = nil
end

local function pruneReplay(s, now)
    local keep = {}
    for _, rid in ipairs(s.order) do
        local e = s.replay[rid]
        if e and now - e.t <= M.config.replaySeconds then
            keep[#keep + 1] = rid
        else
            s.replay[rid] = nil
        end
    end

    while #keep > M.config.replaySize do
        s.replay[table.remove(keep, 1)] = nil
    end

    s.order = keep
end

-- Replay-cache key: client session id + request id (RC4). A new addon
-- session (new sid) can never be answered from an earlier session's entry,
-- even when its request id repeats; the same sid + rid always replays.
function M.replayKey(sid, rid)
    return tostring(sid) .. ':' .. tostring(rid)
end

-- s.sid is the session id of the request being handled (set in onCommand).
local function remember(s, rid, frames, now)
    local key = M.replayKey(s.sid, rid)
    if s.replay[key] == nil then
        s.order[#s.order + 1] = key
    end

    s.replay[key] = { frames = frames, t = now }
    pruneReplay(s, now)
end

-----------------------------------
-- Response builders
-----------------------------------
function M.buildSnapshot(player)
    local list = { { 'v', '1' } }
    list[#list + 1] = { 'ch', tostring(player:getID()) }
    list[#list + 1] = { 'z', tostring(player:getZoneID()) }
    balancePairs(list, M.balances(player))

    local cats =
    {
        { 'H', M.HP_COUNT },
        { 'S', M.SG_COUNT },
        { 'G', M.GC_COUNT },
        { 'R', M.RP_COUNT },
    }

    local ctx       = {}
    local priceKeys = {}
    for _, c in ipairs(cats) do
        local cat, count = c[1], c[2]
        local bits       = {}
        local perDest    = {}
        local tally      = {}
        local orderSeen  = {}
        for id = 0, count - 1 do
            if validDest(M.destination(cat, id)) then
                if M.isUnlocked(player, cat, id) then
                    bits[id] = true
                end

                local o = M.encodeOffers(M.offers(player, cat, id, ctx))
                perDest[#perDest + 1] = { id, o }
                if tally[o] == nil then
                    tally[o] = 0
                    orderSeen[#orderSeen + 1] = o
                end

                tally[o] = tally[o] + 1
            end
        end

        list[#list + 1] = { 'u' .. cat, M.encodeBitmap(bits, count) }

        -- default = most common offer list (ties: first seen)
        local default, best = 'n0', -1
        for _, o in ipairs(orderSeen) do
            if tally[o] > best then
                default, best = o, tally[o]
            end
        end

        local overrides = {}
        for _, e in ipairs(perDest) do
            if e[2] ~= default then
                overrides[#overrides + 1] = string.format('%d~%s', e[1], e[2])
            end
        end

        priceKeys[#priceKeys + 1] = { 'p' .. cat, default }
        if #overrides > 0 then
            priceKeys[#priceKeys + 1] = { 'x' .. cat, table.concat(overrides, '.') }
        end
    end

    for _, kv in ipairs(priceKeys) do
        list[#list + 1] = kv
    end

    local block = M.travelBlock(player)
    list[#list + 1] = { 'ok', block and ('0.' .. block) or '1' }

    return 'S', M.encodeBody(list)
end

function M.buildError(code, extra, player)
    local list = { { 'v', '1' }, { 'e', code } }
    if code == 'VERSION' then
        list[#list + 1] = { 'sv', tostring(M.VERSION) }
    end

    for _, kv in ipairs(extra or {}) do
        list[#list + 1] = kv
    end

    if player then
        local ok, b = pcall(M.balances, player)
        if ok then
            balancePairs(list, b)
        end
    end

    return 'E', M.encodeBody(list)
end

-----------------------------------
-- Travel: validation (no side effects)
-----------------------------------
-- Returns 'plan', plan  or  'reply', kind, body.
-- May raise (any game API error): the caller answers INTERNAL; nothing has
-- been charged at this point.
function M.planGo(player, req)
    local cat, id, cur, amount = req.cat, req.dest, req.cur, req.amount

    local dest = M.destination(cat, id)
    if not validDest(dest) then
        return 'reply', M.buildError('BADDEST', nil, player)
    end

    if not M.isUnlocked(player, cat, id) then
        return 'reply', M.buildError('LOCKED', nil, player)
    end

    local block = M.travelBlock(player)
    if block then
        return 'reply', M.buildError(block, nil, player)
    end

    if player:getZoneID() == dest[5] and player:checkDistance(dest[1], dest[2], dest[3]) <= M.config.hereDistance then
        return 'reply', M.buildError('HERE', nil, player)
    end

    local offers   = M.offers(player, cat, id, {})
    local offerStr = M.encodeOffers(offers)
    local price    = nil
    local isFree   = offers[1].cur == 'f'
    if offers[1].cur == 'n' then
        return 'reply', M.buildError('PAYMENT', { { 'need', offerStr } }, player)
    end

    if isFree then
        if cur ~= 'f' then
            -- Client expected to pay but the trip is free now: price changed.
            return 'reply', M.buildError('PRICE', { { 'need', offerStr } }, player)
        end

        price = 0
    else
        if cur == 'f' then
            return 'reply', M.buildError('PRICE', { { 'need', offerStr } }, player)
        end

        for _, o in ipairs(offers) do
            if o.cur == cur then
                price = o.amount
            end
        end

        if price == nil then
            return 'reply', M.buildError('PAYMENT', { { 'need', offerStr } }, player)
        end
    end

    if price ~= amount then
        return 'reply', M.buildError('PRICE', { { 'need', offerStr } }, player)
    end

    local before = M.balances(player)
    if price > 0 and (before[cur] or 0) < price then
        return 'reply', M.buildError('FUNDS', { { 'need', offerStr } }, player)
    end

    return 'plan',
    {
        cat    = cat,
        id     = id,
        dest   = dest,
        payCur = isFree and 'f' or cur,
        price  = price,
        before = before,
    }
end

-----------------------------------
-- Travel: transaction (after validation)
--
-- Each request id ends in exactly one final outcome, which is stored in the
-- replay cache before it is sent (a repeated id never executes again):
--
--   moved             T                 charged once (or free), character moved
--   not charged       E INTERNAL        nothing was taken (debit had no effect,
--                                       or a free trip could not start)
--   refund confirmed  E INTERNAL        a refund was made and the re-read
--                                       balance equals the pre-charge balance
--   uncertain         E UNSURE          payment and/or movement could not be
--                                       established; CURRENCY INCIDENT logged;
--                                       no guessed refund
--
-- T is sent before setPos (so it reaches the client before zoning) and is
-- therefore provisional: when the move then fails, the final E for the same
-- request id follows immediately as a correction (PROTOCOL-FPX1.md Ã‚Â§4.6).
-- A failed setPos is never assumed to have failed: the move state is checked.
-----------------------------------
M.incidents     = {}
M.MAX_INCIDENTS = 100

function M.log(text)
    print(text)
end

local function safeLog(text)
    pcall(M.log, text)
end

local function readBalance(player, cur)
    local ok, v = pcall(function()
        if cur == 'g' then
            return player:getGil()
        elseif cur == 'c' then
            return player:getCP()
        elseif cur == 'i' then
            return player:getCurrency('imperial_standing')
        end
    end)

    if ok and type(v) == 'number' then
        return v
    end

    return nil
end

-- ctx = { player, rid, plan }; info = { stage, detail, amount, observed, err }
local function incident(ctx, info)
    local plan = ctx.plan or {}
    local rec  =
    {
        t        = M.now(),
        rid      = ctx.rid,
        sid      = ctx.sid,
        stage    = info.stage,
        what     = info.detail,
        cat      = plan.cat,
        dest     = plan.id,
        zone     = plan.dest and plan.dest[5],
        cur      = plan.payCur,
        price    = plan.price,
        amount   = info.amount,
        before   = plan.before and plan.payCur and plan.before[plan.payCur],
        observed = info.observed,
        err      = info.err and tostring(info.err) or nil,
    }

    pcall(function()
        rec.char = ctx.player:getID()
    end)

    M.incidents[#M.incidents + 1] = rec
    while #M.incidents > M.MAX_INCIDENTS do
        table.remove(M.incidents, 1)
    end

    safeLog(string.format(
        '[fpxport] CURRENCY INCIDENT char=%s rid=%s sid=%s stage=%s: %s | travel %s %s -> zone %s | %s %s (amount %s) balance before=%s observed=%s | error=%s | manual check required',
        tostring(rec.char), tostring(rec.rid), tostring(rec.sid), tostring(rec.stage), tostring(rec.what),
        tostring(rec.cat), tostring(rec.dest), tostring(rec.zone),
        tostring(rec.cur), tostring(rec.price), tostring(rec.amount),
        tostring(rec.before), tostring(rec.observed), tostring(rec.err)))

    return rec
end

-- Sends frames; a failure is logged and stops the remaining frames.
local function safeSend(player, frames)
    for _, f in ipairs(frames) do
        local ok, err = pcall(function()
            player:printToPlayer(f, M.config.messageChannel)
        end)

        if not ok then
            safeLog('[fpxport] could not send a response frame: ' .. tostring(err))
            return false
        end
    end

    return true
end

local function notice(player, text)
    local ok, err = pcall(function()
        player:printToPlayer(text, M.config.messageChannel)
    end)

    if not ok then
        safeLog('[fpxport] could not send a notice: ' .. tostring(err))
    end
end

-- Debit. Returns 'charged' | 'not_charged' | 'partial', taken, observed | 'uncertain', nil, nil, err
local function debit(player, cur, price, before)
    if price <= 0 or cur == 'f' then
        return 'charged', 0
    end

    local ok, err = pcall(charge, player, cur, price)
    if ok then
        return 'charged', price
    end

    safeLog('[fpxport] debit raised: ' .. tostring(err))

    local after = readBalance(player, cur)
    if after == nil or before == nil then
        return 'uncertain', nil, nil, err
    end

    if after == before then
        return 'not_charged', 0, after, err
    end

    return 'partial', before - after, after, err
end

-- Refund `amount` and confirm it by re-reading the balance, which must equal
-- `expected` (the validated pre-charge balance). Returns confirmed, observed, err.
-- A refund call that raised still counts as confirmed when the balance proves
-- it; a refund call that returned normally does not count without that proof.
local function refundConfirmed(player, cur, amount, expected)
    if amount == nil or amount <= 0 or cur == 'f' then
        return true, nil, nil
    end

    local ok, err = pcall(refund, player, cur, amount)
    if not ok then
        safeLog('[fpxport] refund raised: ' .. tostring(err))
    end

    local observed = readBalance(player, cur)
    return observed ~= nil and observed == expected, observed, (not ok) and err or nil
end

local function errorFrames(rid, code, player)
    local kind, body = M.buildError(code, nil, player) -- balances read under pcall
    return M.frame(rid, kind, body)
end

-- Final error outcome: cache first (replaces a provisional T), then send.
local function finishError(player, s, rid, code, now)
    local frames = errorFrames(rid, code, player)
    remember(s, rid, frames, now)
    safeSend(player, frames)
end

local UNSURE_NOTICE = 'FFXIPort: travel failed on the server and the payment status could not be confirmed. ' ..
    'The server operator has been notified; please check your balance.'

-- After a raising setPos: true = the move took effect or zoning to the
-- destination has started, false = the character is verifiably still away
-- from the destination and not zoning there, nil = cannot be determined.
-- Uses CBaseEntity:getZone(true), which LSB documents as returning the
-- destination zone while the character is zoning.
function M.moveStarted(player, dest)
    local ok, result = pcall(function()
        if player:getZoneID() == dest[5] and player:checkDistance(dest[1], dest[2], dest[3]) <= M.config.hereDistance then
            return true
        end

        local target = player:getZone(true)
        if target ~= nil and target:getID() == dest[5] and player:getZoneID() ~= dest[5] then
            return true
        end

        return false
    end)

    if ok then
        return result
    end

    return nil
end

-- Returns the outcome: 'moved' | 'not_charged' | 'refunded' | 'uncertain'.
function M.executeGo(player, s, rid, plan, now)
    local cur, price = plan.payCur, plan.price
    local before     = plan.before[cur]
    local ctx        = { player = player, rid = rid, sid = s.sid, plan = plan }

    -- 1. Debit
    local outcome, taken, observed, derr = debit(player, cur, price, before)

    if outcome == 'not_charged' then
        finishError(player, s, rid, 'INTERNAL', now)
        notice(player, 'FFXIPort: travel failed on the server; nothing was charged.')
        return 'not_charged'
    elseif outcome == 'partial' then
        if taken > 0 then
            local confirmed, obs, rerr = refundConfirmed(player, cur, taken, before)
            if confirmed then
                finishError(player, s, rid, 'INTERNAL', now)
                notice(player, 'FFXIPort: travel failed on the server; the amount taken was refunded.')
                return 'refunded'
            end

            incident(ctx, { stage = 'debit', detail = 'debit raised after taking currency; refund not confirmed',
                amount = taken, observed = obs, err = rerr or derr })
        else
            incident(ctx, { stage = 'debit', detail = 'debit raised and the balance increased',
                amount = -taken, observed = observed, err = derr })
        end

        s.goUntil = now + M.config.goCooldownSeconds
        finishError(player, s, rid, 'UNSURE', now)
        notice(player, UNSURE_NOTICE)
        return 'uncertain'
    elseif outcome == 'uncertain' then
        incident(ctx, { stage = 'debit', detail = 'debit raised and the balance could not be read',
            amount = price, err = derr })
        s.goUntil = now + M.config.goCooldownSeconds
        finishError(player, s, rid, 'UNSURE', now)
        notice(player, UNSURE_NOTICE)
        return 'uncertain'
    end

    -- 2. Charged (or free): provisional accepted reply. Balances are read if
    --    possible, otherwise derived from the validated pre-charge balances.
    local after = nil
    local okRead, b = pcall(M.balances, player)
    if okRead and type(b) == 'table' then
        after = b
    else
        after = { g = plan.before.g, c = plan.before.c, i = plan.before.i }
        if cur ~= 'f' then
            after[cur] = (after[cur] or 0) - price
        end
    end

    local list = { { 'v', '1' }, { 'c', plan.cat }, { 'd', tostring(plan.id) }, { 'pay', cur .. tostring(price) } }
    balancePairs(list, after)
    local accepted = M.frame(rid, 'T', M.encodeBody(list))

    remember(s, rid, accepted, now)
    s.goUntil = now + M.config.goCooldownSeconds

    -- 3. Report (before the move, so it reaches the client before zoning).
    safeSend(player, accepted)

    -- 4. Move
    local dest = plan.dest
    local moved, merr = pcall(function()
        player:setPos(dest[1], dest[2], dest[3], dest[4], dest[5])
    end)

    if moved then
        return 'moved'
    end

    -- 5. setPos raised: establish what actually happened.
    safeLog('[fpxport] setPos raised: ' .. tostring(merr))

    local started = M.moveStarted(player, dest)

    if started == true then
        return 'moved' -- paid and moving: the accepted reply stands
    elseif started == nil then
        incident(ctx, { stage = 'move', detail = 'setPos raised and the move state could not be determined; not refunded',
            amount = price, err = merr })
        finishError(player, s, rid, 'UNSURE', now)
        notice(player, UNSURE_NOTICE)
        return 'uncertain'
    end

    -- Verifiably not moved: refund and confirm.
    local confirmed, obs, rerr = refundConfirmed(player, cur, price, before)

    if confirmed then
        s.goUntil = 0
        finishError(player, s, rid, 'INTERNAL', now)
        notice(player, price > 0 and 'FFXIPort: travel failed on the server; your payment was refunded.'
            or 'FFXIPort: travel failed on the server; nothing was charged.')
        return price > 0 and 'refunded' or 'not_charged'
    end

    incident(ctx, { stage = 'refund', detail = 'move failed after charging; refund not confirmed',
        amount = price, observed = obs, err = rerr or merr })
    finishError(player, s, rid, 'UNSURE', now)
    notice(player, UNSURE_NOTICE)
    return 'uncertain'
end

-----------------------------------
-- Request entry point
-----------------------------------
local function reply(player, s, rid, kind, body, now, cache)
    local frames = M.frame(rid, kind, body)
    if frames == nil then
        kind, body = M.buildError('INTERNAL')
        frames = M.frame(rid, kind, body)
    end

    if cache and s then
        remember(s, rid, frames, now)
    end

    safeSend(player, frames)
end

function M.onCommand(player, line)
    local now = M.now()
    local req, code, rid = M.parseRequest(line)
    if req == nil then
        local kind, body = M.buildError(code)
        reply(player, nil, rid, kind, body, now, false)
        return
    end

    local okId, charId = pcall(function()
        return player:getID()
    end)

    if not okId then
        safeLog('[fpxport] getID raised: ' .. tostring(charId))
        local kind, body = M.buildError('INTERNAL')
        reply(player, nil, req.rid, kind, body, now, false)
        return
    end

    -- Rate limits and the travel cooldown stay per character (all sessions);
    -- only the replay cache is per client session.
    local s = session(charId)
    s.sid = req.sid
    pruneReplay(s, now)

    local cached = s.replay[M.replayKey(req.sid, req.rid)]
    if cached then
        safeSend(player, cached.frames)
        return
    end

    if req.op == 'SYNC' then
        local recent = {}
        for _, t in ipairs(s.syncTimes) do
            if now - t < M.config.syncWindowSeconds then
                recent[#recent + 1] = t
            end
        end

        s.syncTimes = recent
        if #recent >= M.config.syncWindowMax then
            local kind, body = M.buildError('BUSY')
            reply(player, s, req.rid, kind, body, now, false)
            return
        end

        recent[#recent + 1] = now
        local ok, kind, body = pcall(M.buildSnapshot, player)
        if not ok then
            safeLog('[fpxport] snapshot failed: ' .. tostring(kind))
            kind, body = M.buildError('INTERNAL')
        end

        reply(player, s, req.rid, kind, body, now, true)
        return
    end

    -- GO
    if now < s.goUntil then
        local kind, body = M.buildError('BUSY', nil, player)
        reply(player, s, req.rid, kind, body, now, false)
        return
    end

    local ok, what, a, b = pcall(M.planGo, player, req)
    if not ok then
        -- Validation reads only; nothing has been charged.
        safeLog('[fpxport] validation failed: ' .. tostring(what))
        finishError(player, s, req.rid, 'INTERNAL', now)
        return
    end

    if what == 'reply' then
        reply(player, s, req.rid, a, b, now, true)
        return
    end

    M.executeGo(player, s, req.rid, a, now)
end


-----------------------------------
-- Module registration (LSB module loader)
-----------------------------------
xi = xi or {}
-- 1.2.0: validate the configured prices once at load (errors are logged).
M.applyConfig()

xi.fpxport = M

M.command =
{
    cmdprops =
    {
        permission = 0,
        parameters = 's', -- single 's': the handler passes the whole remaining line
    },
    onTrigger = function(player, line)
        M.onCommand(player, line)
    end,
}

if xi.module and type(xi.module.registerCommand) == 'function' then
    xi.module.registerCommand(M.config.commandName, M.command)
else
    xi.commands = xi.commands or {}
    xi.commands[M.config.commandName] = M.command
end

local m = Module:new('fpxport')

-- Fresh session state on login (clears replay cache and cooldowns of a
-- previous login of the same character).
m:addOverride('xi.player.onGameIn', function(player, firstLogin, zoning)
    super(player, firstLogin, zoning)
    if not zoning then
        M.resetSession(player:getID())
    end
end)

-- Re-assert the command after server start for loaders without registerCommand.
m:addOverride('xi.server.onServerStart', function(...)
    super(...)
    if not (xi.module and type(xi.module.registerCommand) == 'function') then
        xi.commands = xi.commands or {}
        xi.commands[M.config.commandName] = M.command
    end
end)

return m
